def distribute_into_n_buckets_by_value_range(nums, n):
    if len(nums) == 0:
        return [[] for _ in range(n)]
    lo = min(nums)
    hi = max(nums)
    buckets = [[] for _ in range(n)]
    if hi == lo:
        for v in nums:
            buckets[0].append(v)
        return [sorted(b) for b in buckets]
    edges = [lo + (hi - lo) * i / n for i in range(1, n)]
    for v in nums:
        idx = 0
        while idx < len(edges) and v >= edges[idx]:
            idx += 1
        buckets[idx].append(v)
    return [sorted(b) for b in buckets]

